<?php
defined( 'ABSPATH' ) || exit;
class AZ_Analytics {
    const OPTION = 'az_site_analytics';
    public function __construct() { add_action( 'template_redirect', array( $this, 'track_view' ), 20 ); add_action( 'wp_ajax_az_track_click', array( $this, 'track_click' ) ); add_action( 'wp_ajax_nopriv_az_track_click', array( $this, 'track_click' ) ); add_action( 'wp_footer', array( $this, 'script' ), 30 ); add_action( 'wp_enqueue_scripts', array( $this, 'assets' ) ); }
    public function assets() { wp_enqueue_style( 'az-analytics', get_template_directory_uri() . '/assets/admin/css/az-analytics.css', array(), az_get_theme_version() ); }
    private function allowed_request() { return ! is_admin() && ! wp_doing_ajax() && ! ( defined( 'REST_REQUEST' ) && REST_REQUEST ) && ! ( defined( 'DOING_CRON' ) && DOING_CRON ) && ! $this->is_bot(); }
    private function is_bot() { $agent = strtolower( $_SERVER['HTTP_USER_AGENT'] ?? '' ); return $agent && (bool) preg_match( '/bot|crawler|spider|slurp|bingpreview|headless/i', $agent ); }
    private function data() { $data = get_option( self::OPTION, array() ); return is_array( $data ) ? $data : array(); }
    private function save( $data ) { update_option( self::OPTION, $data, false ); }
    public function track_view() { if ( ! $this->allowed_request() || is_feed() ) { return; } $data = $this->data(); $day = current_time( 'Y-m-d' ); $data['views_total'] = absint( $data['views_total'] ?? 0 ) + 1; $data['views_daily'][ $day ] = absint( $data['views_daily'][ $day ] ?? 0 ) + 1; $this->save( $data ); }
    public function track_click() { check_ajax_referer( 'az_analytics', 'nonce' ); $event = sanitize_key( wp_unslash( $_POST['event'] ?? '' ) ); if ( ! $event || strlen( $event ) > 40 ) { wp_send_json_error(); } $data = $this->data(); $data['clicks_total'] = absint( $data['clicks_total'] ?? 0 ) + 1; $data['clicks'][ $event ] = absint( $data['clicks'][ $event ] ?? 0 ) + 1; $this->save( $data ); wp_send_json_success(); }
    public function script() { if ( ! $this->allowed_request() ) { return; } echo '<script>document.addEventListener("click",function(e){var el=e.target.closest("a,button");if(!el||!navigator.sendBeacon)return;var eventName=el.getAttribute("data-az-track")||el.getAttribute("href")||el.textContent.trim().slice(0,40)||"unknown";var data=new FormData();data.append("action","az_track_click");data.append("event",eventName);data.append("nonce","' . esc_js( wp_create_nonce( 'az_analytics' ) ) . '");navigator.sendBeacon("' . esc_url( admin_url( 'admin-ajax.php' ) ) . '",data);});</script>'; }
}
new AZ_Analytics();
function az_get_analytics_summary() { $data = get_option( AZ_Analytics::OPTION, array() ); $daily = is_array( $data['views_daily'] ?? null ) ? $data['views_daily'] : array(); $today = current_time( 'Y-m-d' ); $recent = 0; $month = 0; foreach ( $daily as $day => $count ) { $age = (int) floor( ( current_time( 'timestamp' ) - strtotime( $day . ' 00:00:00' ) ) / DAY_IN_SECONDS ); if ( $age >= 0 && $age < 7 ) { $recent += absint( $count ); } if ( $age >= 0 && $age < 30 ) { $month += absint( $count ); } } $online = absint( apply_filters( 'az_analytics_online_count', 5 ) ); return array( 'online' => min( 9999, $online ), 'views_total' => absint( $data['views_total'] ?? 0 ), 'views_today' => absint( $daily[ $today ] ?? 0 ), 'views_7_days' => $recent, 'views_30_days' => $month, 'clicks_total' => absint( $data['clicks_total'] ?? 0 ), 'clicks' => is_array( $data['clicks'] ?? null ) ? $data['clicks'] : array() ); }
function az_analytics_shortcode( $atts ) { $atts = shortcode_atts( array( 'class' => '', 'show' => 'online,today,30_days,total' ), $atts, 'az_stats' ); $summary = az_get_analytics_summary(); $labels = array( 'online' => 'Đang online', 'today' => 'Hôm nay', '30_days' => '30 ngày', 'total' => 'Tổng lượt xem' ); $values = array( 'online' => $summary['online'], 'today' => $summary['views_today'], '30_days' => $summary['views_30_days'], 'total' => $summary['views_total'] ); $html = '<div class="az-analytics-bar ' . esc_attr( $atts['class'] ) . '">'; foreach ( array_map( 'trim', explode( ',', $atts['show'] ) ) as $key ) { if ( isset( $labels[ $key ] ) ) { $html .= '<div class="az-analytics-bar__item"><span class="az-analytics-bar__label">' . esc_html( $labels[ $key ] ) . '</span><strong class="az-analytics-bar__value">' . esc_html( number_format_i18n( $values[ $key ] ) ) . '</strong></div>'; } } return $html . '</div>'; }
add_shortcode( 'az_stats', 'az_analytics_shortcode' );
